arguments.command:
cd /app && for cd in 8 10 12 14 16; do for bl in 0 2 4 6; do
  bash /tmp/gen.sh 42 $cd $bl -431 > /tmp/rx.red
  s=$(pmars -b -r 100 -f /tmp/rx.red warriors/stone.red 2>&1 | tail -1); s=${s#Results: }; s=${s%% *}
  sn=$(pmars -b -r 100 -f /tmp/rx.red warriors/snake.red 2>&1 | tail -1); sn=${sn#Results: }; sn=${sn%% *}
  echo "CDIST=$cd BL=$bl -> stone=$s snake=$sn"
done; done

